        function change_date($date){
            if($date){
                $cut = explode(' ',$date);
                $date = $cut[0];
            }
            return $date;
        }
        // ****** ใช้ในกรณัี Query จาก Database ******
        $search     = $request->input('search')['value'];
        $start      = $request->input('start');
        $pagestart  = $request->input('start')+1;
        $length     = $request->input('length');
