    public function change_grade_select(Request $request)
    {
        $id             = $request->input('id');
        $grade_proposed         = $request->input('grade_proposed');
        // if(date('Y-m') <= (date('Y').'-2')){
        //     $previousYear = date('Y', strtotime('-1 year'));
        // }else{
            $previousYear = date('Y');
        // }

        $budget = DB::table('tb_budget_action')
        ->select('tb_budget_action.std')
        ->leftJoin('tb_budget','tb_budget.id','=','tb_budget_action.budget_id')
        ->where('tb_budget.year',$previousYear)
        ->where('tb_budget_action.grade_name',$grade_proposed)
        ->first();

        if(!empty($id)){
            foreach($id AS $val){
                $info = DB::table('tb_employee_final_score')
                ->where('tb_employee_final_score.id',$val)
                ->first();
                if($info->salary_type== "Daily"){
                    $current = $info->salary_old;
                }else{
                    $current = $info->salary_month_old;
                }
                if($info->bsalary_wage){
                    $bsalary_wage = $info->bsalary_wage;
                }else{
                    $bsalary_wage = $current;
                }

                $amount_proposed = ($info->amount_proposed?$info->amount_proposed:0);
                if($bsalary_wage > 0 && $budget->std > 0){
                    if($value->service_days > 365){
                        $service_days1 = 1;
                    }else{
                        $service_days1 = $value->service_days/365;
                    }

                    $service_days2 = $service_days1;
                    $amount_proposed = $bsalary_wage*($budget->std/100)*$service_days2;
                }
                if($info->salary_type == "Daily"){
                    $salary_new = round((float)$amount_proposed+(float)$current);
                }else{
                    $salary_new = round((float)$amount_proposed+(float)$current,(trans(request()->segment(1)) == 'manager'?-2:-1));
                }
                $salary_month_new = ($info->salary_month_new?$info->salary_month_new:0);
                if($salary_new > 0){
                    if($info->salary_type == "Daily"){
                        if($info->grade_proposed == 'CD'){
                            $salary_month_newx = $salary_new*27.5;
                            $salary_month_new = round($salary_month_newx,-1);
                        }else{
                            $salary_month_new = round($salary_new)*26;
                        }
                    }else{
                        $salary_month_new = round($salary_new,(trans(request()->segment(1)) == 'manager'?-2:-1));
                    }
                }

                if($info->salary_type == "Daily"){
                    if($grade_proposed == 'CD'){
                        if($info->bsalary_wage){
                            $cal = $info->bsalary_wage*(1+(10/100))*27.5;
                        }else{
                            $cal = $info->salary_old*(1+(10/100))*27.5;
                        }
                        // DB::table('tb_employee_final_score')
                        // ->where('tb_employee_final_score.id', $val )
                        // ->update([
                        //     "salary_type" => 'Monthly',
                        //     "salary_old" => $cal,
                        //     "bsalary_wage" => $cal,
                        //     "salary_month_old" => $cal
                        // ]);
                    }
                }

                if($info->grade_proposed != 'AR'){
                    DB::table('tb_employee_final_score')
                    ->where('tb_employee_final_score.id', $info->id )
                    ->update([
                        "remark_grade" => ''
                    ]);
                    // $remark_grade = '';
                }

                DB::table('tb_employee_final_score')
                ->where('tb_employee_final_score.id', $val )
                ->update([
                    "grade_proposed_old" => ($info->grade_proposed_old?$info->grade_proposed_old:$info->adjust_grade),
                    "grade_proposed" => $grade_proposed,
                    "percent_proposed_old" => ($grade_proposed == 'CD'?10:($budget->std>0?number_format($budget->std,4,'.',''):'')),
                    "percent_proposed" => ($grade_proposed == 'CD'?10:($budget->std>0?$budget->std:'')),
                    "amount_proposed" => ($amount_proposed>0?$amount_proposed:''),
                    "salary_new" => ($salary_new>0?$salary_new:''),
                    "salary_month_new" => ($salary_month_new>0?$salary_month_new:''),

                    "percent_proposed_old_gmdm" => ($grade_proposed == 'CD'?10:($budget->std>0?number_format($budget->std,4,'.',''):0.0000)),
                    "percent_proposed_gmdm" => ($grade_proposed == 'CD'?10:($budget->std>0?$budget->std:0.0000)),
                    "amount_proposed_gmdm" => ($amount_proposed>0?$amount_proposed:0.00),
                    "salary_new_gmdm" => ($salary_new>0?$salary_new:0.00),
                    "salary_month_new_gmdm" => ($salary_month_new>0?$salary_month_new:0.00),
                    "final_by_md_gm_amount" => ($salary_month_new>0?$salary_month_new:''),
                ]);
            }
        }

        // if(date('Y-m') <= (date('Y').'-2')){
        //     $previousYear = date('Y', strtotime('-1 year'));
        // }else{
            $previousYear = date('Y');
        // }
        DB::table('tb_employee_final_score')
        ->where('tb_employee_final_score.rec_year','like','%'.$previousYear.'%')
        ->where('tb_employee_final_score.status_pa','6')
        ->update([
            "status_pa" => '7'
        ]);



        $result = [
            'id'                => $id,
            'grade_proposed'    => $grade_proposed
        ];
        echo json_encode($result);
    }

    public function change_percent_select(Request $request)
    {
        $id             = $request->input('id');
        $percent_proposed         = $request->input('percent_proposed');
        if(!empty($id)){
            foreach($id AS $val){
                $info = DB::table('tb_employee_final_score')
                ->where('tb_employee_final_score.id',$val)
                ->first();
                if($info->salary_type== "Daily"){
                    $current = $info->salary_old;
                }else{
                    $current = $info->salary_month_old;
                }
                if($info->bsalary_wage){
                    $bsalary_wage = $info->bsalary_wage;
                }else{
                    $bsalary_wage = $current;
                }

                $amount_proposed = ($info->amount_proposed?$info->amount_proposed:0);
                if($bsalary_wage > 0 && $percent_proposed >= 0){
                    if($value->service_days > 365){
                        $service_days1 = 1;
                    }else{
                        $service_days1 = $value->service_days/365;
                    }

                    $service_days2 = $service_days1;
                    $amount_proposed = $bsalary_wage*($percent_proposed/100)*$service_days2;
                }
                if($info->salary_type == "Daily"){
                    $salary_new = round((float)$amount_proposed+(float)$current);
                }else{
                    $salary_new = round((float)$amount_proposed+(float)$current,(trans(request()->segment(1)) == 'manager'?-2:-1));
                }
                $salary_month_new = ($info->salary_month_new?$info->salary_month_new:0);
                if($salary_new > 0){
                    if($info->salary_type == "Daily"){
                        if($info->grade_proposed == 'CD'){
                            $salary_month_newx = $salary_new*27.5;
                            $salary_month_new = round($salary_month_newx,-1);
                        }else{
                            $salary_month_new = round($salary_new)*26;
                        }
                    }else{
                        $salary_month_new = round($salary_new,(trans(request()->segment(1)) == 'manager'?-2:-1));
                    }
                }

                DB::table('tb_employee_final_score')
                ->where('tb_employee_final_score.id', $val )
                ->update([
                    "percent_proposed_old" => ($percent_proposed>=0?$percent_proposed:0.0000),
                    "percent_proposed" => ($percent_proposed>=0?$percent_proposed:0.0000),
                    "amount_proposed" => ($amount_proposed>0?$amount_proposed:0.00),
                    "salary_new" => ($salary_new>0?$salary_new:0.00),
                    "salary_month_new" => ($salary_month_new>0?$salary_month_new:0.00),

                    "percent_proposed_old_gmdm" => ($info->percent_proposed>=0?number_format($info->percent_proposed,4,'.',''):0.0000),
                    "percent_proposed_gmdm" => ($percent_proposed>=0?number_format($percent_proposed,4,'.',''):0.0000),
                    "amount_proposed_gmdm" => ($amount_proposed>0?$amount_proposed:0.00),
                    "salary_new_gmdm" => ($salary_new>0?$salary_new:0.00),
                    "salary_month_new_gmdm" => ($salary_month_new>0?$salary_month_new:0.00),
                    "final_by_md_gm_amount" => ($salary_month_new>0?$salary_month_new:0.00),
                ]);
            }
        }

        // if(date('Y-m') <= (date('Y').'-2')){
        //     $previousYear = date('Y', strtotime('-1 year'));
        // }else{
            $previousYear = date('Y');
        // }
        DB::table('tb_employee_final_score')
        ->where('tb_employee_final_score.rec_year','like','%'.$previousYear.'%')
        ->where('tb_employee_final_score.status_pa','6')
        ->update([
            "status_pa" => '7'
        ]);



        $result = [
            'id'                => $id,
            // 'grade_proposed'    => $percent_proposed
        ];
        echo json_encode($result);
    }

