    public function update_position_grade_p(Request $request)
    {
        $id             = $request->input('id');
        $position_code             = $request->input('position_code');
        $change_position_remark             = $request->input('change_position_remark');
        $change_position_reasons             = $request->input('change_position_reasons');
        $grade_proposed             = $request->input('grade_proposed');
        $search_year             = $request->input('search_year');
        $previousYear = $search_year;
        $tb_position = DB::table('tb_position')
        ->where('tb_position.position_code',$position_code)
        ->first();

        $tb_employee = DB::table('tb_employee')
        ->where('tb_employee.id',$id)
        ->first();
        $tb_employee_final_score = DB::table('tb_employee_final_score')
        ->where('tb_employee_final_score.employee_no',$tb_employee->orisoft_no)
        ->where('tb_employee_final_score.rec_year',$search_year)
        ->first();


        if($grade_proposed == 'P' || $grade_proposed == 'CD'){
            DB::table('tb_employee')
            ->where('tb_employee.id', $id )
            ->update([
                "position_code_old" => $tb_employee->position_code,
                "position_code_change" => $position_code,
                // "position_code" => $position_code,
                "position_description_old" => $tb_employee->position_description,
                // "position_description" => $tb_position->position_description,
                "change_position_remark" => $change_position_remark,
                "change_position_reasons" => $change_position_reasons
            ]);
        }else{
            if($tb_employee_final_score->grade_proposed == "P"){
                DB::table('tb_employee')
                ->where('tb_employee.id', $id )
                ->update([
                    "position_code_old" => null,
                    "position_code" => $tb_employee->position_code_old,
                    "position_description_old" => null,
                    "position_description" => $tb_employee->position_description_old,
                    "change_position_remark" => $change_position_remark,
                    "change_position_reasons" => $change_position_reasons
                ]);
            }else{
                DB::table('tb_employee')
                ->where('tb_employee.id', $id )
                ->update([
                    "position_code_old" => $tb_employee->position_code,
                    "position_code" => $tb_employee->position_code,
                    "position_description_old" => $tb_employee->position_description,
                    "position_description" => $tb_employee->position_description,
                    "change_position_remark" => $change_position_remark,
                    "change_position_reasons" => $change_position_reasons
                ]);
            }

        }

        // if(date('Y-m') <= (date('Y').'-2')){
        //     $previousYear = date('Y', strtotime('-1 year'));
        // }else{

        // }
        if($grade_proposed != 'P' && $grade_proposed != 'CD'){
            DB::table('tb_employee_final_score')
            ->where('tb_employee_final_score.employee_no', $tb_employee->orisoft_no )
            ->where('tb_employee_final_score.rec_year',$previousYear)
            ->update([
                "remark_grade" => $change_position_reasons
            ]);
            $result = [
                'id'                => $id,
                'remark_grade'                => $change_position_reasons,
                'position_description'=> $tb_employee->position_description
            ];
        }else{
            DB::table('tb_employee_final_score')
            ->where('tb_employee_final_score.employee_no', $tb_employee->orisoft_no )
            ->where('tb_employee_final_score.rec_year',$previousYear)
            ->update([
                "remark_grade" => $tb_employee->position_description.' -> '.$tb_position->position_description
            ]);
            $result = [
                'id'                => $id,
                'remark_grade'                => $tb_employee->position_description.' -> '.$tb_position->position_description,
                'position_description'=> $tb_employee->position_description
            ];
        }



        echo json_encode($result);
    }
