    public function save_jd(Request $request)
    {
        $id             = $request->input('id');
        $search_year             = $request->input('search_year');
        $jd_position             = $request->input('jd_position');
        $jd_position_description             = $request->input('jd_position_description');
        $jd_company             = $request->input('jd_company');
        $jd_level             = $request->input('jd_level');
        $jd_division             = $request->input('jd_division');
        $jd_department             = $request->input('jd_department');
        $jd_section             = $request->input('jd_section');
        $jd_position_backup             = $request->input('jd_position_backup');
        $jd_position_report             = $request->input('jd_position_report');
        $jd_organization_position             = $request->input('jd_organization_position');
        $jd_organization_level             = $request->input('jd_organization_level');
        $KEY_RESPONSIBILITY             = $request->input('KEY_RESPONSIBILITY');
        $TASK             = $request->input('TASK');
        $KNOWLEDGE             = $request->input('KNOWLEDGE');
        $SKILLS             = $request->input('SKILLS');
        $PERSONALITY_TRAITS             = $request->input('PERSONALITY_TRAITS');
        $previousYear = $search_year;
        // $previousYear = 2024;
        $info = DB::table('tb_employee')
        ->where('tb_employee.id',$id)
        ->first();
        DB::table('tb_employee_final_score')
        ->where('tb_employee_final_score.employee_no', $info->orisoft_no)
        ->where('tb_employee_final_score.rec_year','like','%'.$previousYear.'%')
        ->update([
            "JD_POSITION" => $jd_position,
            "JD_PREFIX" => $jd_position_description,
            "JD_COMPANY" => $jd_company,
            "JD_GRADE_CODE" => $jd_level,
            "JD_DIVISION_CODE" => $jd_division,
            "JD_DEPARTMENT_CODE" => $jd_department,
            "JD_SECTION_CODE" => $jd_section,
            "JD_POSITION_BACKUP" => $jd_position_backup,
            "JD_POSITION_REPORT_THIS_ROLE" => $jd_position_report,
        ]);

        $tb_employee_final_score = DB::table('tb_employee_final_score')
        ->where('tb_employee_final_score.employee_no', $info->orisoft_no)
        ->where('tb_employee_final_score.rec_year','like','%'.$previousYear.'%')
        ->first();
        // $result = [
        //     'tb_employee_final_score'                => $tb_employee_final_score
        // ];



        // echo json_encode($result);
        // exit;
        if(isset($jd_organization_position)){
            DB::table('organization_chart')->where('JD_TEMPLATE_ID', $tb_employee_final_score->id)->delete();
            DB::table('organization_chart')->insert([
                "POSITION" => $jd_organization_position,
                "LEVEL" => $jd_organization_level,
                "JD_TEMPLATE_ID" => $tb_employee_final_score->id,
            ]);
        }

        if(isset($TASK)){
            if(count($TASK) > 0){
                DB::table('jd_tasks')->where('JD_TEMPLATE_ID', $tb_employee_final_score->id)->delete();
                foreach ($TASK as $key => $value) {
                    DB::table('jd_tasks')->insert([
                        "KEY_RESPONSIBILITY" => $KEY_RESPONSIBILITY,
                        "TASK" => $value,
                        "JD_TEMPLATE_ID" => $tb_employee_final_score->id,
                    ]);
                }
            }
        }
        if(isset($KNOWLEDGE)){
            if(count($KNOWLEDGE) > 0){
                DB::table('jd_knowledge')->where('JD_TEMPLATE_ID', $tb_employee_final_score->id)->delete();
                foreach ($KNOWLEDGE as $key => $value) {
                    DB::table('jd_knowledge')->insert([
                        "KNOWLEDGE" => $value,
                        "JD_TEMPLATE_ID" => $tb_employee_final_score->id,
                    ]);
                }
            }
        }
        if(isset($SKILLS)){
            if(count($SKILLS) > 0){
                DB::table('jd_skills')->where('JD_TEMPLATE_ID', $tb_employee_final_score->id)->delete();
                foreach ($SKILLS as $key => $value) {
                    DB::table('jd_skills')->insert([
                        "SKILLS" => $value,
                        "JD_TEMPLATE_ID" => $tb_employee_final_score->id,
                    ]);
                }
            }
        }
        if(isset($PERSONALITY_TRAITS)){
            if(count($PERSONALITY_TRAITS) > 0){
                DB::table('jd_personality')->where('JD_TEMPLATE_ID', $tb_employee_final_score->id)->delete();
                foreach ($PERSONALITY_TRAITS as $key => $value) {
                    DB::table('jd_personality')->insert([
                        "PERSONALITY_TRAITS" => $value,
                        "JD_TEMPLATE_ID" => $tb_employee_final_score->id,
                    ]);
                }
            }
        }

        $result = [
            'status'                => 200
        ];



        echo json_encode($result);
    }

