    public function check_new_position(Request $request)
    {
        $new_position_code      = $request->input('new_position_code');
        $info = DB::table('tb_position')
        ->where('tb_position.position_code',$new_position_code)
        ->count();
        echo json_encode($info);
    }

    public function add_new_position(Request $request)
    {
        $new_position_code      = $request->input('new_position_code');
        $new_position_description      = $request->input('new_position_description');
        $CreateEmployeeModel = Position::create([
            "position_code" => $new_position_code,
            "position_description" => $new_position_description,
            "created_by" => Auth::user()->id,
            "updated_by" => '0',
            "created" => date('Y-m-d H:i:s'),
            "updated" => null,
        ]);

        $info = DB::table('tb_position')
        ->where('tb_position.position_code',$new_position_code)
        ->count();
        echo json_encode($info);
    }

