    public function export_excel_approve_jd(Request $request)
    {
        set_time_limit(300);
        // $year = $request->query('year', date('Y'));
        $year       = $request->input('search_year');
        // $orisoft_code = Auth::user()->orisoft_code;
        $data = DB::table('tb_employee_final_score')
        ->select(
            'tb_employee_final_score.employee_no',
            'tb_employee.title_en',
            'tb_employee.title_th',
            'tb_employee.employee_local_name_en',
            'tb_employee.employee_local_name_th',
            'tb_employee.position_code_change',
            'tb_employee.position_code',
            'tb_employee.position_description',
            'tb_employee.division_code',
            'tb_employee.division_description',
            'tb_employee.department_code',
            'tb_employee.department_description',
            'tb_employee.section_code',
            'tb_employee.section_description',
            'tb_employee.grade_code',
            'tb_employee.grade_description',
            'tb_employee.date_joined',
            'tb_employee_final_score.id',
            'tb_employee_final_score.service_days',
            'tb_employee_final_score.attendance_sl',
            'tb_employee_final_score.attendance_pl',
            'tb_employee_final_score.attendance_late',
            'tb_employee_final_score.attendance_abs',
            'tb_employee_final_score.attendance_abt',
            'tb_employee_final_score.attendance_cl',
            'tb_employee_final_score.attendance_ol',
            'tb_employee_final_score.attendance_sus',
            'tb_employee_final_score.attendance_wwar',
            'tb_employee_final_score.attendance_vwar',
            'tb_employee_final_score.adjust_grade_old2',
            'tb_employee_final_score.adjust_grade_old3',
            'tb_employee_final_score.grade_proposed',

            'tb_employee_final_score.total_score',
            'tb_employee_final_score.adjust_grade',

            'tb_employee_final_score.JD_POSITION',
            'tb_employee_final_score.JD_PREFIX',
            'tb_employee_final_score.JD_COMPANY',
            'tb_employee_final_score.JD_GRADE_CODE',
            'tb_employee_final_score.JD_DIVISION_CODE',
            'tb_employee_final_score.JD_DEPARTMENT_CODE',
            'tb_employee_final_score.JD_SECTION_CODE',
            'tb_employee_final_score.JD_POSITION_BACKUP',
            'tb_employee_final_score.JD_POSITION_REPORT_THIS_ROLE',
            'tb_employee_final_score.JD_HIGHER_POSITION',
            'tb_employee_final_score.JD_LEVEL'
        )
        ->leftJoin('tb_employee','tb_employee.orisoft_no','=','tb_employee_final_score.employee_no')
        ->where('tb_employee_final_score.rec_year',$year)
        ->where('tb_employee_final_score.grade_proposed', 'P')
        ->orderBy('division_code','ASC')
        ->orderBy('department_code','ASC')
        ->orderBy('section_code','ASC')
        ->get();
        // dd($data);
        // exit;
        $excel = public_path('upload/orisoft/')."Template_jd.xlsx";
        $reader = new Reader();
        $spreadsheet = $reader->load($excel);
        $sheet = $spreadsheet->getActiveSheet();
        $sheet = $spreadsheet->getSheet(0);

        $previousYear3 = Carbon::createFromFormat('Y', $year)->subYears(2)->year;
        $previousYear2 = Carbon::createFromFormat('Y', $year)->subYears()->year;
        // $previousYear1 = Carbon::createFromFormat('Y', $year)->subYear()->year;

        $numrow = 2;
        $final_score = [];
        if(count($data)>0){
            foreach ($data as $key => $value) {


                $spreadsheet
                ->getActiveSheet()
                ->getStyle('A'.$numrow.':AX'.$numrow)
                ->getBorders()
                ->getAllBorders()
                ->setBorderStyle(Border::BORDER_THIN)
                ->setColor(new Color('000000'));
                $sheet->setCellValue('A'.$numrow, $value->employee_no);
                $sheet->setCellValue('B'.$numrow, $value->title_en);
                $sheet->setCellValue('C'.$numrow, $value->title_th);
                $sheet->setCellValue('D'.$numrow, $value->employee_local_name_en);
                $sheet->setCellValue('E'.$numrow, $value->employee_local_name_th);

                $position_description = $value->position_description;
                if($value->position_code_change){
                    $position_description_data = DB::table('tb_position')->where('position_code',$value->position_code_change)->first();
                    $position_description = $position_description_data->position_description;
                }


                $sheet->setCellValue('F'.$numrow, ($value->position_code_change?$value->position_code_change:$value->position_code));
                $sheet->setCellValue('G'.$numrow, $position_description);
                $sheet->setCellValue('H'.$numrow, $value->division_code);
                $sheet->setCellValue('I'.$numrow, $value->division_description);
                $sheet->setCellValue('J'.$numrow, $value->department_code);
                $sheet->setCellValue('K'.$numrow, $value->department_description);

                $sheet->setCellValue('L'.$numrow, $value->section_code);
                $sheet->setCellValue('M'.$numrow, $value->section_description);
                $sheet->setCellValue('N'.$numrow, $value->grade_code);

                $sheet->setCellValue('O'.$numrow, $value->grade_description);

                $formattedDate = date("d/m/Y", strtotime($value->date_joined));
                $sheet->setCellValue('P'.$numrow, $formattedDate);
                $sheet->setCellValue('Q'.$numrow, $value->service_days);



                $sheet->setCellValue('R'.$numrow, $value->total_score);
                $sheet->setCellValue('S'.$numrow, $value->adjust_grade);
                $sheet->setCellValue('T'.$numrow, $value->grade_proposed);

                $sheet->setCellValue('U'.$numrow, $value->JD_POSITION);
                $sheet->setCellValue('V'.$numrow, $value->JD_PREFIX);
                $sheet->setCellValue('W'.$numrow, $value->JD_COMPANY);
                $sheet->setCellValue('X'.$numrow, $value->JD_GRADE_CODE);
                $sheet->setCellValue('Y'.$numrow, $value->JD_DIVISION_CODE);
                $sheet->setCellValue('Z'.$numrow, $value->JD_DEPARTMENT_CODE);
                $sheet->setCellValue('AA'.$numrow, $value->JD_SECTION_CODE);
                $sheet->setCellValue('AB'.$numrow, $value->JD_POSITION_BACKUP);
                $sheet->setCellValue('AC'.$numrow, $value->JD_POSITION_REPORT_THIS_ROLE);
                // $sheet->setCellValue('AD'.$numrow, $value->JD_HIGHER_POSITION);
                // $sheet->setCellValue('AE'.$numrow, $value->JD_LEVEL);

                $data_organization_chart = DB::table('organization_chart')
                ->where('organization_chart.JD_TEMPLATE_ID',$value->id)
                ->first();
                $html_organization_chart = '';
                $html_organization_chart2 = '';
                if($data_organization_chart){
                    if($data_organization_chart->POSITION){
                        $html_organization_chart =  $data_organization_chart->POSITION;
                    }
                    if($data_organization_chart->LEVEL){
                        $html_organization_chart2 =  $data_organization_chart->LEVEL;
                    }
                }
                $sheet->setCellValue('AD'.$numrow, $html_organization_chart);
                $sheet->setCellValue('AE'.$numrow, $html_organization_chart2);
                $emp_id = $value->id;
                $data_jd_tasks = DB::table('jd_tasks')
                ->where('jd_tasks.JD_TEMPLATE_ID',$emp_id)
                ->get();
                $html_jd_tasks = '';
                $html_jd_tasks2 = '';
                if(count($data_jd_tasks)>0){
                    foreach ($data_jd_tasks as $key => $value) {
                        if($key == 0){
                            $html_jd_tasks .=  $value->KEY_RESPONSIBILITY.' - ';
                        }
                        $html_jd_tasks2 .=  $value->TASK."\n";
                    }
                }
                $sheet->setCellValue('AF'.$numrow, $html_jd_tasks);
                $sheet->setCellValue('AG'.$numrow, $html_jd_tasks2);
                $sheet->getStyle('AF' . $numrow)->getAlignment()->setWrapText(true);


                $data_jd_knowledge = DB::table('jd_knowledge')
                ->where('jd_knowledge.JD_TEMPLATE_ID',$emp_id)
                ->get();
                $html_jd_knowledge = '';
                if(count($data_jd_knowledge)>0){
                    foreach ($data_jd_knowledge as $key => $value) {
                        $html_jd_knowledge .=  $value->KNOWLEDGE."\n";
                    }
                }
                $sheet->setCellValue('AH'.$numrow, $html_jd_knowledge);
                $sheet->getStyle('AH' . $numrow)->getAlignment()->setWrapText(true);

                $data_jd_skills = DB::table('jd_skills')
                ->where('jd_skills.JD_TEMPLATE_ID',$emp_id)
                ->get();
                $html_jd_skills = '';
                if(count($data_jd_skills)>0){
                    foreach ($data_jd_skills as $key => $value) {
                        $html_jd_skills .=  $value->SKILLS."\n";
                    }
                }
                $sheet->setCellValue('AI'.$numrow, $html_jd_skills);
                $sheet->getStyle('AI' . $numrow)->getAlignment()->setWrapText(true);

                $data_jd_personality = DB::table('jd_personality')
                ->where('jd_personality.JD_TEMPLATE_ID',$emp_id)
                ->get();
                $html_jd_personality = '';
                if(count($data_jd_personality)>0){
                    foreach ($data_jd_personality as $key => $value) {
                        $html_jd_personality .=  $value->PERSONALITY_TRAITS."\n";
                    }
                }
                $sheet->setCellValue('AJ'.$numrow, $html_jd_personality);
                $sheet->getStyle('AJ' . $numrow)->getAlignment()->setWrapText(true);

                $numrow++;
            }
        }
        // กำหนดชื่อไฟล์ excel ที่ต้องการ
        $writer = new Xlsx($spreadsheet);

        $previousYear1 = Carbon::createFromFormat('Y', $year)->subYear()->year;

        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="Checklist_Attendance_'.$year.'.xls"');
        header('Cache-Control: max-age=0');

        $writer = \PhpOffice\PhpSpreadsheet\IOFactory::createWriter($spreadsheet, 'Xls');
        $writer->save('php://output');
    }

