                $sheet->setCellValue('N'.$numrow, $value->grade_code);

                $sheet->setCellValue('O'.$numrow, $value->grade_description);

                $formattedDate = date("d/m/Y", strtotime($value->date_joined));
                $sheet->setCellValue('P'.$numrow, $formattedDate);
                $sheet->setCellValue('Q'.$numrow, $value->salary_old);
                $sheet->setCellValue('R'.$numrow, $value->service_days);
                $sheet->setCellValue('S'.$numrow, $value->attendance_sl);
                $sheet->setCellValue('T'.$numrow, $value->attendance_pl);
                $sheet->setCellValue('U'.$numrow, $value->attendance_late);
                $sheet->setCellValue('V'.$numrow, $value->attendance_abs);
                $sheet->setCellValue('W'.$numrow, $value->attendance_abt);
                $sheet->setCellValue('X'.$numrow, $value->attendance_cl);
                $sheet->setCellValue('Y'.$numrow, $value->attendance_ol);
                $sheet->setCellValue('Z'.$numrow, $value->attendance_sus);
                $sheet->setCellValue('AA'.$numrow, $value->attendance_wwar);

                $sheet->setCellValue('AB'.$numrow, $value->attendance_vwar);
                $sheet->setCellValue('AC'.$numrow, $value->adjust_grade_old2);
                $sheet->setCellValue('AD'.$numrow, $value->adjust_grade_old3);
                $sheet->setCellValue('AE'.$numrow, $value->grade_proposed);
                $sheet->setCellValue('AF'.$numrow, ($value->not_up_salary && $value->not_up_salary != ""?$value->employee_no:''));
                $numrow++;
            }
        }
        // กำหนดชื่อไฟล์ excel ที่ต้องการ
        $writer = new Xlsx($spreadsheet);

        $previousYear1 = Carbon::createFromFormat('Y', $year)->subYear()->year;

        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="Checklist_Attendance_'.$year.'.xls"');
        header('Cache-Control: max-age=0');

        $writer = \PhpOffice\PhpSpreadsheet\IOFactory::createWriter($spreadsheet, 'Xls');
        $writer->save('php://output');
    }
}
